//! FIPS 203 ML-KEM 后量子密钥封装（Module-Lattice-Based KEM，前身 CRYSTALS-Kyber）。
//!
//! 三个参数集，公钥 / 私钥 / 密文 / 共享密钥均为十六进制（1 字节 = 2 位）：
//!
//! | 标识            | 公钥 ek          | 私钥 dk          | 密文 ct          | 共享密钥     |
//! |-----------------|------------------|------------------|------------------|--------------|
//! | `ml-kem-512`    | 1600 位（800 B） | 3264 位（1632 B）| 1536 位（768 B） | 64 位（32 B）|
//! | `ml-kem-768`    | 2368 位（1184 B）| 4800 位（2400 B）| 2176 位（1088 B）| 64 位（32 B）|
//! | `ml-kem-1024`   | 3136 位（1568 B）| 6336 位（3168 B）| 3136 位（1568 B）| 64 位（32 B）|
//!
//! 错误映射：十六进制非法 → [`Error::InvalidHex`]；公钥 / 私钥字节数不符，或公钥
//! （含私钥内嵌的公钥）未通过 FIPS 203 §7.2 的 modulus check（t̂ 存在 ≥ q 的系数）→
//! [`Error::InvalidKey`]；密文字节数不符 → [`Error::InvalidKeyLength`]。
//!
//! **隐式拒绝**：密文被篡改（或私钥与公钥不配对）时，解封装**不报错**，而是返回
//! 一个与封装端不同的伪随机共享密钥（FIPS 203 §7.3）。这是标准行为，调用方应以
//! 「共享密钥不匹配」而非「出错」来理解，契约注释里亦有强调。
//!
//! 对应 PHP 版 `Pqc/` 的密钥封装服务与 `Contract/KeyEncapsulationInterface`。

use ml_kem::array::typenum::Unsigned;
use ml_kem::kem::{Decapsulate, Encapsulate};
use ml_kem::{Ciphertext, Encoded, EncodedSizeUser, KemCore, MlKem512, MlKem768, MlKem1024};
use rand_core::OsRng;

use crate::contract::{Identified, KeyEncapsulation};
use crate::error::{Error, Result};
use crate::internal::{hex_decode, hex_encode};

/// ML-KEM-512（FIPS 203 安全类别 1，≈AES-128 强度）。
#[derive(Debug, Default, Clone, Copy)]
pub struct MlKem512Kem;

impl MlKem512Kem {
    pub const IDENTIFIER: &'static str = "ml-kem-512";

    pub fn new() -> Self {
        Self
    }
}

impl Identified for MlKem512Kem {
    fn identifier(&self) -> &str {
        Self::IDENTIFIER
    }
}

impl KeyEncapsulation for MlKem512Kem {
    fn generate(&self) -> Result<(String, String)> {
        generate_hex::<MlKem512>()
    }

    fn encapsulate(&self, public_key_hex: &str) -> Result<(String, String)> {
        encapsulate_hex::<MlKem512>(public_key_hex, "ML-KEM-512")
    }

    fn decapsulate(&self, ciphertext_hex: &str, private_key_hex: &str) -> Result<String> {
        decapsulate_hex::<MlKem512>(
            ciphertext_hex,
            private_key_hex,
            "ML-KEM-512",
            "ML-KEM-512 ciphertext",
        )
    }
}

